package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.io.StringWriter;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.Arrays;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.CharsetNames;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_TarArchiveOutputStream_TriageGen2Test {

    @Test
    public void testConstructorWithAllParameters() throws IOException {
        OutputStream os = new ByteArrayOutputStream();
        int blockSize = 512;
        int recordSize = 128;
        String encoding = "UTF-8";

        TarArchiveOutputStream taos = new TarArchiveOutputStream(os, blockSize, recordSize, encoding);

        Assert.assertNotNull(taos);
        Assert.assertEquals(recordSize, taos.getRecordSize());
    }














}

